use vstd::prelude::*;

verus! {

fn interleave(s1: &Vec<i32>, s2: &Vec<i32>, s3: &Vec<i32>) -> (res: Vec<i32>)
    requires
        s1.len() == s2.len(),
        s2.len() == s3.len(),
        // triple length fits in i32 range
        (3 * (s1.len() as u32)) <= (i32::MAX as u32),
    ensures
        res.len() == 3 * s1.len(),
        // For each index i in [0, n), output contains s1[i], s2[i], s3[i] interleaved
        forall(|i: usize| (i < s1.len()) ==> (
            res[3 * i] == s1[i] &&
            res[3 * i + 1] == s2[i] &&
            res[3 * i + 2] == s3[i]
        )),
{
    let n = s1.len();
    let mut res = Vec::<i32>::with_capacity(3 * n);
    let mut i: usize = 0;

    while i < n
        invariant
            i <= n,
            res.len() == 3 * i,
            forall(|j: usize| (j < i) ==> (
                res[3 * j] == s1[j] &&
                res[3 * j + 1] == s2[j] &&
                res[3 * j + 2] == s3[j]
            )),
        decreases n - i,
    {
        res.push(s1[i]);
        res.push(s2[i]);
        res.push(s3[i]);
        i = i + 1;
    }

    res
}

}
